// n8n Code node "Build Claude request" (Run Once for Each Item)
// Input: the Webhook item, with the log at body.raw_log.
// Output: { request } for the HTTP Request node to send as its JSON body.
// build.mjs fills in SYSTEM_PROMPT and SCHEMA from system-prompt.txt and schema.json
// when it writes workflow.json. Edit those files, not the copy in workflow.json.
const SYSTEM_PROMPT = "You are a clinical telemetry ingestion parser. Your sole task is to process unformatted daily updates, biometric logs, voice note transcripts, and workout notes, then extract them into a normalized, single JSON object.\n\nOPERATIONAL RULES:\n1. Strict Extraction: Extract ONLY explicitly stated data. Never interpolate, guess, or synthesize missing values. If a field is omitted in the raw text, return `null`.\n2. Type Safety: Ensure numeric values (weights, reps, step counts) are strictly numbers, not strings. Strip units (\"kg\", \"lbs\", \"steps\") during extraction.\n3. Workout Parsing: Structure exercise data sequentially into an array of objects containing movement, weight, sets, reps, and optional notes.\n4. Schema Enforcement: You MUST return raw JSON adhering strictly to the required output schema. Do NOT include Markdown code blocks (no ```json wrapper), commentary, or leading/trailing prose.";
const SCHEMA = {
  "type": "object",
  "properties": {
    "timestamp": {
      "type": [
        "string",
        "null"
      ],
      "format": "date-time"
    },
    "biometrics": {
      "type": "object",
      "properties": {
        "body_weight_kg": {
          "type": [
            "number",
            "null"
          ]
        },
        "step_count": {
          "type": [
            "integer",
            "null"
          ]
        },
        "resting_heart_rate": {
          "type": [
            "integer",
            "null"
          ]
        },
        "sleep_hours": {
          "type": [
            "number",
            "null"
          ]
        }
      },
      "required": [
        "body_weight_kg",
        "step_count",
        "resting_heart_rate",
        "sleep_hours"
      ],
      "additionalProperties": false
    },
    "nutrition": {
      "type": "object",
      "properties": {
        "protocol": {
          "type": [
            "string",
            "null"
          ]
        },
        "total_calories": {
          "type": [
            "integer",
            "null"
          ]
        },
        "protein_grams": {
          "type": [
            "integer",
            "null"
          ]
        },
        "adherence": {
          "type": [
            "boolean",
            "null"
          ]
        }
      },
      "required": [
        "protocol",
        "total_calories",
        "protein_grams",
        "adherence"
      ],
      "additionalProperties": false
    },
    "training": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "exercise": {
            "type": "string"
          },
          "weight_kg": {
            "type": [
              "number",
              "null"
            ]
          },
          "sets": {
            "type": "integer"
          },
          "reps": {
            "type": "integer"
          },
          "notes": {
            "type": [
              "string",
              "null"
            ]
          }
        },
        "required": [
          "exercise",
          "weight_kg",
          "sets",
          "reps",
          "notes"
        ],
        "additionalProperties": false
      }
    },
    "flags": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Log any anomalies, fatigue warnings, or explicit performance dips mentioned in the text."
    }
  },
  "required": [
    "timestamp",
    "biometrics",
    "nutrition",
    "training",
    "flags"
  ],
  "additionalProperties": false
};

const rawLog = String($input.item.json.body?.raw_log ?? '').trim();
if (!rawLog) {
  throw new Error('body.raw_log is empty');
}

return {
  json: {
    raw_log: rawLog,
    request: {
      model: 'claude-opus-5-5',
      max_tokens: 16000,
      output_config: {
        effort: 'low',
        format: { type: 'json_schema', schema: SCHEMA },
      },
      fallbacks: 'default',
      system: SYSTEM_PROMPT,
      messages: [
        {
          role: 'user',
          content: `Extract the telemetry metrics from this log into JSON:\n\n${rawLog}`,
        },
      ],
    },
  },
};

// n8n Code node "Parse Claude response" (Run Once for Each Item)
// Input: the HTTP Request node's output (the raw Messages API response).
// The response can hold thinking and fallback blocks before the text, so
// find the text block instead of reading content[0].
const res = $input.item.json;
const ingestedAt = new Date().toISOString();

function fail(error, extra = {}) {
  return {
    json: {
      success: false,
      error,
      stop_reason: res.stop_reason ?? null,
      model: res.model ?? null,
      ...extra,
      ingested_at: ingestedAt,
    },
  };
}

if (res.type === 'error' || res.error) {
  return fail(`API error: ${res.error?.type ?? 'unknown'}: ${res.error?.message ?? ''}`);
}
if (res.stop_reason === 'refusal') {
  return fail('Claude declined the request', { stop_details: res.stop_details ?? null });
}
if (res.stop_reason === 'max_tokens') {
  return fail('Output hit max_tokens and is incomplete');
}

const text = (res.content ?? [])
  .filter((block) => block.type === 'text')
  .map((block) => block.text)
  .join('')
  .trim();

try {
  const data = JSON.parse(text);
  return {
    json: {
      success: true,
      data,
      model: res.model,
      usage: res.usage ?? null,
      ingested_at: ingestedAt,
    },
  };
} catch (error) {
  return fail('JSON parsing failed', { raw_output: text });
}
